  "No pending requests at the moment.": "ಪ್ರಸ್ತುತ ಯಾವುದೇ ಬಾಕಿ ಇರುವ ವಿನಂತಿಗಳಿಲ್ಲ.",
  "No requests at the moment.": "ಪ್ರಸ್ತುತ ಯಾವುದೇ ವಿನಂತಿಗಳಿಲ್ಲ.",
  "You don't have any pending claims waiting for donor confirmation. Explore the live food feed to request fresh surplus.": "ದಾನಿಯ ದೃಢೀಕರಣಕ್ಕಾಗಿ ಕಾಯುತ್ತಿರುವ ಯಾವುದೇ ಬಾಕಿ ಕ್ಲೈಮ್‌ಗಳು ನಿಮ್ಮಲ್ಲಿಲ್ಲ. ತಾಜಾ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ವಿನಂತಿಸಲು ಲೈವ್ ಆಹಾರ ಫೀಡ್ ಅನ್ನು ಅನ್ವೇಷಿಸಿ.",
  "No active pickups currently scheduled. When an NGO claims your surplus food, collection details and OTP will appear here.": "ಪ್ರಸ್ತುತ ಯಾವುದೇ ಸಕ್ರಿಯ ಪಿಕಪ್‌ಗಳನ್ನು ನಿಗದಿಪಡಿಸಲಾಗಿಲ್ಲ. ಎನ್‌ಜಿಒ ನಿಮ್ಮ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ಸ್ವೀಕರಿಸಿದಾಗ, ಸಂಗ್ರಹಣೆಯ ವಿವರಗಳು ಮತ್ತು OTP ಇಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "No active collections scheduled. When an NGO claims your banquet meals, driver credentials and handover OTP will appear here.": "ಯಾವುದೇ ಸಕ್ರಿಯ ಸಂಗ್ರಹಣೆಗಳು ನಿಗದಿಯಾಗಿಲ್ಲ. ಎನ್‌ಜಿಒ ನಿಮ್ಮ ಔತಣಕೂಟದ ಊಟವನ್ನು ಸ್ವೀಕರಿಸಿದಾಗ, ಚಾಲಕರ ವಿವರಗಳು ಮತ್ತು ಹಸ್ತಾಂತರ OTP ಇಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "No in-transit pickups right now.": "ಪ್ರಸ್ತುತ ಸಾಗಣೆಯಲ್ಲಿ ಯಾವುದೇ ಪಿಕಪ್‌ಗಳಿಲ್ಲ.",
  "When you request and accept food donations, assigned drivers and verification OTPs will appear here.": "ನೀವು ಆಹಾರ ದಾನಗಳನ್ನು ವಿನಂತಿಸಿದಾಗ ಮತ್ತು ಸ್ವೀಕರಿಸಿದಾಗ, ನಿಯೋಜಿತ ಚಾಲಕರು ಮತ್ತು ಪರಿಶೀಲನೆ OTP ಗಳು ಇಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "No verified deliveries found": "ಯಾವುದೇ ಪರಿಶೀಲಿಸಿದ ವಿತರಣೆಗಳು ಕಂಡುಬಂದಿಲ್ಲ",
  "Completed handovers will appear in this ledger once OTP verification is finished.": "OTP ಪರಿಶೀಲನೆ ಪೂರ್ಣಗೊಂಡ ನಂತರ ಪೂರ್ಣಗೊಂಡ ಹಸ್ತಾಂತರಗಳು ಈ ಲೆಡ್ಜರ್‌ನಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "No donations found": "ಯಾವುದೇ ದಾನಗಳು ಕಂಡುಬಂದಿಲ್ಲ",
  "No hotel donations found": "ಯಾವುದೇ ಹೋಟೆಲ್ ದಾನಗಳು ಕಂಡುಬಂದಿಲ್ಲ",
  "You haven't listed any household donations in this category yet.": "ನೀವು ಇನ್ನೂ ಈ ವರ್ಗದಲ್ಲಿ ಯಾವುದೇ ಮನೆಯ ದಾನಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿಲ್ಲ.",
  "No matching surplus food found": "ಹೊಂದಾಣಿಕೆಯ ಯಾವುದೇ ಹೆಚ್ಚುವರಿ ಆಹಾರ ಕಂಡುಬಂದಿಲ್ಲ",
  "Try adjusting your search terms or filters.": "ನಿಮ್ಮ ಹುಡುಕಾಟದ ಪದಗಳು ಅಥವಾ ಫಿಲ್ಟರ್‌ಗಳನ್ನು ಸರಿಹೊಂದಿಸಲು ಪ್ರಯತ್ನಿಸಿ.",
  "No completed deliveries yet.": "ಇನ್ನೂ ಯಾವುದೇ ಪೂರ್ಣಗೊಂಡ ವಿತರಣೆಗಳಿಲ್ಲ.",
  "Food Donation Listed!": "ಆಹಾರ ದಾನವನ್ನು ಪಟ್ಟಿ ಮಾಡಲಾಗಿದೆ!",
  "Thank you for sharing with your community. Nearby verified volunteers have been notified to collect your food.": "ನಿಮ್ಮ ಸಮುದಾಯದೊಂದಿಗೆ ಹಂಚಿಕೊಂಡಿದ್ದಕ್ಕಾಗಿ ಧನ್ಯವಾದಗಳು. ನಿಮ್ಮ ಆಹಾರವನ್ನು ಸಂಗ್ರಹಿಸಲು ಹತ್ತಿರದ ಪರಿಶೀಲಿಸಿದ ಸ್ವಯಂಸೇವಕರಿಗೆ ತಿಳಿಸಲಾಗಿದೆ.",
  "Food Request Placed!": "ಆಹಾರ ವಿನಂತಿಯನ್ನು ಸಲ್ಲಿಸಲಾಗಿದೆ!",
  "Profile changes saved successfully.": "ಪ್ರೊಫೈಲ್ ಬದಲಾವಣೆಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಉಳಿಸಲಾಗಿದೆ.",
  "Organization profile updated successfully.": "ಸಂಸ್ಥೆಯ ಪ್ರೊಫೈಲ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ.",
  "Hotel profile updated successfully!": "ಹೋಟೆಲ್ ಪ್ರೊಫೈಲ್ ಯಶಸ್ವಿಯಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ!",
  "Lifetime donations on record:": "ದಾಖಲೆಯಲ್ಲಿರುವ ಸಾರ್ವಕಾಲಿಕ ದಾನಗಳು:",
  "Newly posted donations will appear here once verified by the collecting NGO.": "ಸಂಗ್ರಹಿಸುವ ಎನ್‌ಜಿಒ ಪರಿಶೀಲಿಸಿದ ನಂತರ ಹೊಸದಾಗಿ ಪೋಸ್ಟ್ ಮಾಡಲಾದ ದಾನಗಳು ಇಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "Food Name / What are you sharing? *": "ಆಹಾರದ ಹೆಸರು / ನೀವು ಏನನ್ನು ಹಂಚಿಕೊಳ್ಳುತ್ತಿದ್ದೀರಿ? *",
