  "Catering & Takeaway Excess": "ಕ್ಯಾಟರಿಂಗ್ ಮತ್ತು ಪಾರ್ಸಲ್ ಹೆಚ್ಚುವರಿ ಆಹಾರ",
  "Other Kitchen Surplus": "ಇತರ ಅಡುಗೆಮನೆಯ ಹೆಚ್ಚುವರಿ ಆಹಾರ",
