  "Connect": "ಸಂಪರ್ಕಿಸಿ",
  "Linked": "ಜೋಡಿಸಲಾಗಿದೆ",
  "Receive urgent notifications when surplus is claimed or route dispatched": "ಹೆಚ್ಚುವರಿ ಆಹಾರ ಕ್ಲೇಮ್ ಆದಾಗ ಅಥವಾ ವಾಹನ ಹೊರಟಾಗ ತುರ್ತು ಅಧಿಸೂಚನೆಗಳನ್ನು ಪಡೆಯಿರಿ",
  "Play gentle notification sound on live NGO claims & IoT anomalies": "ಪ್ಲೇ ಮಾಡಿ ಸೌಮ್ಯ ಅಧಿಸೂಚನೆ ಧ್ವನಿ ಮೇಲೆ ಲೈವ್ NGO ಕ್ಲೈಮ್‌ಗಳು & IoT ವೈಪರೀತ್ಯಗಳು",
  "Auto-deliver forecasted meal requirements every morning at 06:00 AM": "ಅಂದಾಜಿಸಿದ ಊಟದ ಅಗತ್ಯಗಳನ್ನು ಪ್ರತಿದಿನ ಬೆಳಿಗ್ಗೆ 06:00 ಕ್ಕೆ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಕಳುಹಿಸಿ",
  "Surplus exceeding this amount automatically triggers matching priority to nearest certified NGOs.": "ಈ ಪ್ರಮಾಣ ಮೀರಿದ ಹೆಚ್ಚುವರಿ ಆಹಾರಕ್ಕೆ ಹತ್ತಿರದ ಪ್ರಮಾಣೀಕೃತ NGO ಗಳೊಂದಿಗೆ ಹೊಂದಾಣಿಕೆಯಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಆದ್ಯತೆ ಸಿಗುತ್ತದೆ.",
  "Alerts with model confidence above this score require warden or plant manager confirmation.": "ಎಚ್ಚರಿಕೆಗಳು ಜೊತೆಗೆ ಮಾದರಿ ವಿಶ್ವಾಸಾರ್ಹತೆ ಮೇಲೆ ಈ ಅಂಕ ಅಗತ್ಯವಿದೆ ವಾರ್ಡನ್ ಅಥವಾ ಸ್ಥಾವರ ವ್ಯವಸ್ಥಾಪಕ ದೃಢೀಕರಣ.",
  "Your institutional facility is verified under the National Food Recovery Network. All surplus donations receive immutable digital chain-of-custody hashes.": "ನಿಮ್ಮ ಸಂಸ್ಥೆಯ ಸೌಲಭ್ಯವನ್ನು ರಾಷ್ಟ್ರೀಯ ಆಹಾರ ಉಳಿತಾಯ ಜಾಲದಡಿ ಪರಿಶೀಲಿಸಲಾಗಿದೆ. ಎಲ್ಲಾ ಹೆಚ್ಚುವರಿ ದಾನಗಳಿಗೆ ಬದಲಾಯಿಸಲಾಗದ ಡಿಜಿಟಲ್ ಹಸ್ತಾಂತರ ದಾಖಲೆ ಸಿಗುತ್ತದೆ.",
  "Settings apply across all modules": "ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಅನ್ವಯಿಸಿ ಉದ್ದಕ್ಕೂ ಎಲ್ಲಾ ಮಾಡ್ಯೂಲ್‌ಗಳು",
  "Prioritizes zero food shortages by buffering portions slightly (+5%).": "ಆದ್ಯತೆ ನೀಡುತ್ತದೆ ಶೂನ್ಯ ಆಹಾರ ಕೊರತೆಗಳು ಮೂಲಕ ಬಫರಿಂಗ್ ಭಾಗಗಳು ಸ್ವಲ್ಪ ಮಟ್ಟಿಗೆ (+5%).",
  "Optimal trade-off minimizing both food waste and stockouts (Recommended).": "ಆಹಾರ ತ್ಯಾಜ್ಯ ಮತ್ತು ಕೊರತೆ ಎರಡನ್ನೂ ಕಡಿಮೆ ಮಾಡುವ ಉತ್ತಮ ಸಮತೋಲನ (ಶಿಫಾರಸು).",
  "Strict zero-waste optimization targeting exact attendance figures.": "ಕಟ್ಟುನಿಟ್ಟಾದ ಶೂನ್ಯ-ತ್ಯಾಜ್ಯ ಆಪ್ಟಿಮೈಸೇಶನ್ ಗುರಿಯಾಗಿಸಿಕೊಂಡು ನಿಖರ ಹಾಜರಾತಿ ಅಂಕಿಅಂಶಗಳು.",
