  "Incident Ticket Logged with FoodWise Admin!": "ಘಟನೆ ಟಿಕೆಟ್ ಲಾಗ್ ಮಾಡಲಾಗಿದೆ ಜೊತೆಗೆ FoodWise ನಿರ್ವಾಹಕ!",
  "Your complaint has been assigned to the FoodWise Rapid Response Quality Desk. If food is inedible, our auto-matching engine is locating immediate backup surplus for your shelter.": "ನಿಮ್ಮ ದೂರನ್ನು FoodWise ತ್ವರಿತ ಪ್ರತಿಕ್ರಿಯೆ ಗುಣಮಟ್ಟ ವಿಭಾಗಕ್ಕೆ ನೀಡಲಾಗಿದೆ. ಆಹಾರ ತಿನ್ನಲು ಯೋಗ್ಯವಲ್ಲದಿದ್ದರೆ, ನಮ್ಮ ಸ್ವಯಂ-ಹೊಂದಾಣಿಕೆ ವ್ಯವಸ್ಥೆ ನಿಮ್ಮ ಆಶ್ರಯಕ್ಕೆ ತಕ್ಷಣದ ಬದಲಿ ಆಹಾರವನ್ನು ಹುಡುಕುತ್ತಿದೆ.",
