  "Select the incident category to trigger the appropriate FoodWise Admin resolution workflow": "ಸೂಕ್ತ FoodWise ನಿರ್ವಾಹಕ ಪರಿಹಾರ ಪ್ರಕ್ರಿಯೆ ಆರಂಭಿಸಲು ಘಟನೆಯ ವರ್ಗವನ್ನು ಆಯ್ಕೆಮಾಡಿ",
