  "NGO Volunteer Callback Number": "NGO ಸ್ವಯಂಸೇವಕ ಕಾಲ್‌ಬ್ಯಾಕ್ ಸಂಖ್ಯೆ",
  "+91 XXXXX XXXXX (For Admin to call immediately)": "+91 XXXXX XXXXX (ನಿರ್ವಾಹಕರು ತಕ್ಷಣ ಕರೆ ಮಾಡಲು)",
  "Describe the Incident *": "ಘಟನೆಯನ್ನು ವಿವರಿಸಿ *",
  "State clearly what happened. e.g. 'Food smelled sour when opened at the shelter', or 'Driver arrived 2 hours late and food was cold', or 'Claimed 50 kg but only 20 kg received'...": "ಏನಾಯಿತು ಎಂದು ಸ್ಪಷ್ಟವಾಗಿ ತಿಳಿಸಿ. ಉದಾ. 'ಆಶ್ರಯದಲ್ಲಿ ತೆರೆದಾಗ ಆಹಾರ ಹುಳಿ ವಾಸನೆ ಬರುತ್ತಿತ್ತು', ಅಥವಾ 'ಚಾಲಕರು 2 ಗಂಟೆ ತಡವಾಗಿ ಬಂದರು ಮತ್ತು ಆಹಾರ ತಣ್ಣಗಾಗಿತ್ತು', ಅಥವಾ '50 ಕೆಜಿ ಎಂದು ಹೇಳಲಾಗಿತ್ತು ಆದರೆ 20 ಕೆಜಿ ಮಾತ್ರ ಬಂತು'...",
