  "Upload Photo Evidence": "ಫೋಟೋ ಸಾಕ್ಷ್ಯ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ",
  "Take a quick photo of the packaging, temperature probe, or spoiled food for instant admin verification": "ತಕ್ಷಣದ ನಿರ್ವಾಹಕ ಪರಿಶೀಲನೆಗಾಗಿ ಪ್ಯಾಕೇಜಿಂಗ್, ತಾಪಮಾನ ಮಾಪಕ ಅಥವಾ ಹಾಳಾದ ಆಹಾರದ ಫೋಟೋ ತೆಗೆಯಿರಿ",
  "Photo Evidence Attached": "ಫೋಟೋ ಪುರಾವೆ ಲಗತ್ತಿಸಲಾಗಿದೆ",
  "Take Photo with Camera": "ತೆಗೆದುಕೊಳ್ಳಿ ಫೋಟೋ ಜೊತೆಗೆ ಕ್ಯಾಮೆರಾ",
  "Live snap of food container / label": "ಆಹಾರದ ಪಾತ್ರೆ / ಲೇಬಲ್‌ನ ತಕ್ಷಣದ ಫೋಟೋ",
  "Upload from Gallery / Files": "ಗ್ಯಾಲರಿ / ಫೈಲ್‌ಗಳಿಂದ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ",
