  "Machine micro-failures are the #1 invisible cause of industrial food waste. A worn peeling drum blade causes 15% peel loss instead of 8% — creating 500 kg of avoidable scrap per shift. We detect blade wear BEFORE it ruins batches.": "ಯಂತ್ರಗಳ ಸಣ್ಣ ದೋಷಗಳು ಕೈಗಾರಿಕಾ ಆಹಾರ ತ್ಯಾಜ್ಯದ ಪ್ರಮುಖ ಅಗೋಚರ ಕಾರಣ. ಸವೆದ ಸಿಪ್ಪೆ ಡ್ರಮ್ ಬ್ಲೇಡ್ 8% ಬದಲು 15% ಸಿಪ್ಪೆ ನಷ್ಟ ಉಂಟುಮಾಡಿ ಪ್ರತಿ ಪಾಳಿಗೆ 500 kg ತಪ್ಪಿಸಬಹುದಾದ ಉಳಿಕೆ ಸೃಷ್ಟಿಸುತ್ತದೆ. ಬ್ಯಾಚ್ ಹಾಳಾಗುವ ಮೊದಲೇ ನಾವು ಬ್ಲೇಡ್ ಸವೆತ ಪತ್ತೆ ಮಾಡುತ್ತೇವೆ.",
